WITH src AS (SELECT * FROM transactions WHERE amount BETWEEN 2400 AND 2500 OR txn_type = 'DEBIT'), transactions_stats AS (SELECT merchant, SUM(CASE WHEN merchant = '7-Eleven' THEN amount ELSE 0 END) AS 7_eleven_amount FROM src GROUP BY merchant) SELECT merchant, 7_eleven_amount FROM transactions_stats ORDER BY merchant DESC LIMIT 10;
